@TestOn('vm')
library;

import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:vibermate_app/core/api/control_api.dart';

// Reads a file the Runtime's tests generate, so it runs on the VM only.
void main() {
  test('every kind of settled question the Runtime sends can be read', () {
    // Generated by the Runtime's own code
    // (internal/toolapproval/resolved_sample_test.go).
    final samples =
        jsonDecode(
              File(
                '../../api/samples/approvals-resolved.json',
              ).readAsStringSync(),
            )
            as List<Object?>;
    final decided = decidedApprovalsOf(samples);
    expect(decided, hasLength(samples.length));
    expect(decided.map((record) => record.kind).toSet(), {
      'network_ask',
      'tool_intent',
      'client_root_ask',
    });
    expect(decided.map((record) => record.state).toSet(), {
      'allowed',
      'denied',
      'expired',
      'canceled',
    });
  });
}
